// Independent oracles only. Production classes are extracted from the final dist by the Node test.
public class ContractHarness {
 static long checks=0;static Random random=new Random(20261017L);static LinkedHashMap<String,Long> groups=new LinkedHashMap<>();
 static void eq(long a,long b,String name){checks++;if(a!=b)throw new AssertionError(name+": "+a+" != "+b);}
 static void yes(boolean b,String name){checks++;if(!b)throw new AssertionError(name);}
 static void group(String s,long start){groups.put(s,checks-start);}
 static List<int[]> pairs(int[] a,int t){var p=new ArrayList<int[]>();for(int i=0;i<a.length;i++)for(int j=i+1;j<a.length;j++)if((long)a[i]+a[j]==t)p.add(new int[]{i,j});return p;}
 static void pair(int[] a,int t,int[] p){yes(p.length==2&&p[0]!=p[1]&&p[0]>=0&&p[1]>=0&&p[0]<a.length&&p[1]<a.length&&(long)a[p[0]]+a[p[1]]==t,"two-sum mathematical pair");}
 static long triangles(int[] a){long c=0;for(int i=0;i<a.length;i++)for(int j=i+1;j<a.length;j++)for(int k=j+1;k<a.length;k++)if((long)a[i]+a[j]>a[k]&&(long)a[i]+a[k]>a[j]&&(long)a[j]+a[k]>a[i])c++;return c;}
 static int shortest(int[] a,int target){int best=Integer.MAX_VALUE;for(int i=0;i<a.length;i++){long sum=0;for(int j=i;j<a.length;j++){sum+=a[j];if(sum>=target)best=Math.min(best,j-i+1);}}return best==Integer.MAX_VALUE?0:best;}
 static long starts(TreeNode n,long sum,int target){if(n==null)return 0;sum+=n.val;return (sum==target?1:0)+starts(n.left,sum,target)+starts(n.right,sum,target);}
 static long paths(TreeNode n,int target){return n==null?0:starts(n,0,target)+paths(n.left,target)+paths(n.right,target);}
 static Fold437.TreeNode copyTree(TreeNode n){if(n==null)return null;var c=new Fold437.TreeNode(n.val);c.left=copyTree(n.left);c.right=copyTree(n.right);return c;}
 static BigInteger[][] exactGrid(int[][] a){int m=a.length,n=a[0].length;BigInteger[][] dp=new BigInteger[m][n];for(int i=0;i<m;i++)for(int j=0;j<n;j++){dp[i][j]=BigInteger.ZERO;if(a[i][j]==1)continue;if(i==0&&j==0)dp[i][j]=BigInteger.ONE;else{if(i>0)dp[i][j]=dp[i][j].add(dp[i-1][j]);if(j>0)dp[i][j]=dp[i][j].add(dp[i][j-1]);}}return dp;}
 static BigInteger choose(int n,int k){BigInteger r=BigInteger.ONE;for(int i=1;i<=k;i++)r=r.multiply(BigInteger.valueOf(n-i+1)).divide(BigInteger.valueOf(i));return r;}
 static String cli(int id,String data) throws Exception {InputStream oldIn=System.in;PrintStream oldOut=System.out;var out=new ByteArrayOutputStream();try{System.setIn(new ByteArrayInputStream(data.getBytes(java.nio.charset.StandardCharsets.UTF_8)));System.setOut(new PrintStream(out));switch(id){case 1:Fold1.main(new String[0]);break;case 611:Fold611.main(new String[0]);break;case 378:Fold378.main(new String[0]);break;case 437:Fold437.main(new String[0]);break;case 62:Fold62.main(new String[0]);break;case 63:Fold63.main(new String[0]);break;case 440:Fold440.main(new String[0]);break;default:throw new AssertionError();}}finally{System.setIn(oldIn);System.setOut(oldOut);}return out.toString(java.nio.charset.StandardCharsets.UTF_8).trim();}
 static String gridInput(int[][] a){var s=new StringBuilder().append(a.length).append(' ').append(a[0].length).append('\n');for(int[] row:a){for(int x:row)s.append(x).append(' ');s.append('\n');}return s.toString();}
 public static void main(String[] args)throws Exception{
 long begin=checks;var one=new LC1();int trials=0;
 while(trials<1200){int[] a=new int[2+random.nextInt(8)];for(int i=0;i<a.length;i++)a[i]=random.nextInt(21)-10;int t=random.nextInt(31)-15;if(pairs(a,t).size()!=1)continue;pair(a,t,one.twoSum(a,t));pair(a,t,HashTemplate.twoSum(a,t));pair(a,t,Fold1.solve(a,t));trials++;}
 int[] boundary={1000000000,-1000000000,0};pair(boundary,1000000000,one.twoSum(boundary,1000000000));pair(boundary,-1000000000,one.twoSum(boundary,-1000000000));
 yes(cli(1,"4\n2 7 11 15\n9\n").equals("0 1"),"LC1 CLI");group("LC1 and topic template/CLI",begin);
 begin=checks;var tri=new LC611();for(int q=0;q<600;q++){int[] a=new int[1+random.nextInt(14)];for(int i=0;i<a.length;i++)a[i]=random.nextInt(11);long expected=triangles(a);eq(tri.triangleNumber(a.clone()),expected,"triangle brute");eq(Fold611.solve(a.clone()),expected,"triangle fold brute");}int[] thousand=new int[1000];Arrays.fill(thousand,1000);eq(tri.triangleNumber(thousand.clone()),166167000,"triangle official maximum count");eq(Fold611.solve(thousand.clone()),166167000,"triangle fold max count");yes(cli(611,"4\n2 2 3 4\n").equals("3"),"triangle CLI");group("LC611",begin);
 begin=checks;var win=new LC209();for(int q=0;q<1000;q++){int[] a=new int[1+random.nextInt(30)];for(int i=0;i<a.length;i++)a[i]=1+random.nextInt(10000);int t=1+random.nextInt(150000);eq(win.minSubArrayLen(t,a),shortest(a,t),"window oracle");}int[] hundredK=new int[100000];Arrays.fill(hundredK,10000);eq(win.minSubArrayLen(1000000000,hundredK),100000,"window official max sum");eq(win.minSubArrayLen(7,new int[]{2,3,1,2,4,3}),2,"window original example");group("LC209",begin);
 begin=checks;var matrix=new LC378();for(int q=0;q<100;q++){int n=1+random.nextInt(9);int[][] a=new int[n][n];for(int i=0;i<n;i++)for(int j=0;j<n;j++)a[i][j]=Math.max(i>0?a[i-1][j]:-30,j>0?a[i][j-1]:-30)+random.nextInt(4);int[] flat=Arrays.stream(a).flatMapToInt(Arrays::stream).sorted().toArray();for(int k=1;k<=n*n;k++){eq(matrix.kthSmallest(a,k),flat[k-1],"matrix sort oracle");eq(Fold378.solve(a,k),flat[k-1],"matrix fold sort oracle");}}int[][] large=new int[300][300];for(int[] row:large)Arrays.fill(row,1000000000);large[0][0]=-1000000000;eq(matrix.kthSmallest(large,90000),1000000000,"matrix max n/k");eq(matrix.kthSmallest(large,1),-1000000000,"matrix first k");yes(cli(378,"2 3\n1 2\n2 3\n").equals("2"),"matrix CLI");group("LC378",begin);
 begin=checks;var tree=new LC437();eq(tree.pathSum(null,0),0,"empty tree");for(int q=0;q<250;q++){int n=1+random.nextInt(24);TreeNode[] nodes=new TreeNode[n];for(int i=0;i<n;i++)nodes[i]=new TreeNode(random.nextInt(7)-3);for(int i=1;i<n;i++){TreeNode parent=nodes[(i-1)/2];if(i%2==1)parent.left=nodes[i];else parent.right=nodes[i];}for(int target=-8;target<=8;target++){long expected=paths(nodes[0],target);eq(tree.pathSum(nodes[0],target),expected,"tree enumerated start/end oracle");eq(Fold437.pathSum(copyTree(nodes[0]),target),expected,"tree fold oracle");}}TreeNode zero=new TreeNode(0),tail=zero;for(int i=1;i<1000;i++){tail.right=new TreeNode(0);tail=tail.right;}eq(tree.pathSum(zero,0),500500,"zero chain official maximum count");eq(Fold437.pathSum(copyTree(zero),0),500500,"zero chain fold maximum count");TreeNode extremes=new TreeNode(1000000000);extremes.right=new TreeNode(1000000000);extremes.right.right=new TreeNode(-1000000000);eq(tree.pathSum(extremes,0),1,"long prefix");yes(cli(437,"1 1 1\n1\n").equals("3"),"tree CLI");group("LC437",begin);
 begin=checks;var up=new LC62();for(int m=1;m<=100;m++)for(int n=1;n<=100;n++){BigInteger expected=choose(m+n-2,m-1);if(expected.compareTo(BigInteger.valueOf(2000000000))<=0){eq(up.uniquePaths(m,n),expected.longValueExact(),"paths binomial oracle");}}yes(cli(62,"3 7\n").equals("28"),"unique paths CLI");eq(up.uniquePaths(100,1),1,"max one dimension");group("LC62",begin);
 begin=checks;var obstacles=new LC63();for(int q=0;q<700;q++){int m=1+random.nextInt(12),n=1+random.nextInt(12);int[][] a=new int[m][n];for(int[] row:a)for(int j=0;j<n;j++)row[j]=random.nextInt(4)==0?1:0;BigInteger[][] exact=exactGrid(a);BigInteger expected=exact[m-1][n-1];eq(obstacles.uniquePathsWithObstacles(a),expected.longValueExact(),"obstacle BigInteger oracle");if(q<30)yes(cli(63,gridInput(a)).equals(expected.toString()),"obstacle CLI oracle");}int[][] dead=new int[100][100];Arrays.fill(dead[99],1);BigInteger[][] deadExact=exactGrid(dead);yes(deadExact[98][99].compareTo(BigInteger.valueOf(Integer.MAX_VALUE))>0,"large dead-end counts exceed int");eq(obstacles.uniquePathsWithObstacles(dead),0,"intermediate wrap does not corrupt bounded final 0");yes(cli(63,gridInput(dead)).equals("0"),"fold wrap final 0");int[][] corridor=new int[100][100];for(int i=1;i<99;i++)corridor[i][98]=1;Arrays.fill(corridor[99],1);corridor[99][99]=0;BigInteger[][] corridorExact=exactGrid(corridor);yes(corridorExact[98][97].compareTo(BigInteger.valueOf(Integer.MAX_VALUE))>0,"unreachable-to-target branch exceeds int");eq(corridorExact[99][99].longValueExact(),1,"unique isolated corridor");eq(obstacles.uniquePathsWithObstacles(corridor),1,"intermediate wrap final 1");yes(cli(63,gridInput(corridor)).equals("1"),"fold wrap final 1");group("LC63",begin);
 begin=checks;var lex=new LC440();for(int n=1;n<=300;n++){ArrayList<Integer> order=new ArrayList<>();for(int x=1;x<=n;x++)order.add(x);order.sort(Comparator.comparing(String::valueOf));for(int k=1;k<=n;k++){eq(lex.findKthNumber(n,k),order.get(k-1),"lex string-sort oracle");eq(Fold440.solve(n,k),order.get(k-1),"lex fold string-sort oracle");}}eq(lex.findKthNumber(1000000000,1),1,"max n first");eq(lex.findKthNumber(1000000000,1000000000),999999999,"max n final");yes(cli(440,"13 2\n").equals("10"),"lex CLI");group("LC440",begin);
 // These are observations outside the restored original contracts, not failures of original solutions.
 int[] outside1={Integer.MAX_VALUE,Integer.MAX_VALUE,-3,1};int[] got=one.twoSum(outside1,-2);yes((long)outside1[got[0]]+outside1[got[1]]!=-2,"outside LC1 false pair observed");
 eq(tri.triangleNumber(new int[]{Integer.MAX_VALUE,Integer.MAX_VALUE,Integer.MAX_VALUE}),0,"outside triangle side range wraps");int[] beyondCount=new int[2346];Arrays.fill(beyondCount,1);eq(tri.triangleNumber(beyondCount),(int)choose(2346,3).longValueExact(),"outside triangle count range wraps");
 eq(win.minSubArrayLen(2000000000,new int[]{1500000000,1500000000}),0,"outside window range wraps");eq(choose(38,19).longValueExact(),35345263800L,"20x20 exact count");eq(up.uniquePaths(20,20),(int)35345263800L,"outside LC62 answer bound wraps");eq(obstacles.uniquePathsWithObstacles(new int[20][20]),(int)35345263800L,"outside LC63 answer bound wraps");
 for(var e:groups.entrySet())System.out.println(e.getKey()+": "+e.getValue()+" checks passed");System.out.println("TOTAL="+checks);System.out.println("Outside-contract observations: LC1 false pair; LC611 side/count wrap; LC209 sum wrap; LC62/63 20x20=35345263800 exceeds original final-answer bound.");
 }
}
